<?php require __DIR__.'/config/app.php'; if(user()) go(role_home((string)user()['role'])); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $key='login_'.sha1((string)($_SERVER['REMOTE_ADDR']??'')); $_SESSION[$key]??=['n'=>0,'at'=>time()]; if(time()-$_SESSION[$key]['at']>900) $_SESSION[$key]=['n'=>0,'at'=>time()]; if($_SESSION[$key]['n']>=8){$error='Too many attempts. Please try again in 15 minutes.';} elseif($email){try{ensure_profile_schema();ensure_committee_schema();$q=db()->prepare('SELECT id,name,email,password_hash,role,is_active,avatar_path FROM users WHERE email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();if($u&&$u['is_active']&&password_verify((string)($_POST['password']??''),$u['password_hash'])){if($u['role']==='student'&&!preg_match('/@marwadiuniversity\.ac\.in$/i',$u['email'])){$error='Student sign-in requires an @marwadiuniversity.ac.in email address.';}else{session_regenerate_id(true);unset($u['password_hash'],$u['is_active']);$_SESSION['user']=$u;$_SESSION[$key]['n']=0;go(role_home((string)$u['role']));}}else{$error='Email or password was not recognized.';}if($error)$_SESSION[$key]['n']++;}catch(Throwable $e){$error='Database is not ready. Import database/eventhub_db.sql, then try again.';}}else{$error='Enter a valid email address.';}}$pageTitle='Sign in';$bodyClass='auth-page-shell login-page';$hideSiteNav=true;require __DIR__.'/includes/header.php';?><main class="auth-page"><form class="auth-card" method="post"><img class="auth-logo" src="<?=url('assets/images/marwadi-chandarana-group.png')?>" alt="Marwadi University"><h1>Welcome to EventHub</h1><p>Sign in with your Marwadi University account.</p><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><input type="hidden" name="_csrf" value="<?=csrf()?>"><label>Email address<input type="email" name="email" autocomplete="username" required value="<?=e($_POST['email']??'')?>"></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="btn primary full">Sign in</button><small>Student email must end in @marwadiuniversity.ac.in.</small><p class="auth-switch">New student? <a href="<?=url('register.php')?>">Create an account</a></p></form></main><?php require __DIR__.'/includes/footer.php';
